class Solution {
    public int[] decompressRLElist(int[] nums){
        int length=0;
        for(int i=0;i<nums.length;i+=2)length+=nums[i];
        int[] answer=new int[length];
        int write=0;
        for(int i=0;i<nums.length;i+=2)for(int count=0;count<nums[i];count++)answer[write++]=nums[i+1];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun decompressRLElist(nums:IntArray):IntArray{
        var length=0;
        for(i in nums.indices step 2)length+=nums[i];
        val answer=IntArray(length);
        var write=0;
        for(i in nums.indices step 2)repeat(nums[i]){
            answer[write++]=nums[i+1]
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: vector<int> decompressRLElist(vector<int>& nums){
        vector<int> answer;
        for(int i=0;i<(int)nums.size();i+=2)answer.insert(answer.end(),nums[i],nums[i+1]);
        return answer;
    }
};
